import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { detectMessageType, parseSosXml } from '../../src/xml/parser';
import { BetCancelEvent, BetSettlementEvent, OddsChangeEvent } from '../../src/types';

describe('detectMessageType', () => {
  it('names each message by its root element, and nothing for anything else', () => {
    for (const type of ['odds_change', 'bet_settlement', 'bet_stop', 'bet_cancel', 'fixture_change', 'snapshot_complete', 'alive']) {
      assert.equal(detectMessageType(`<${type} product="1"/>`), type);
    }
    assert.equal(detectMessageType('<fixtures/>'), null);
  });
});

describe('parseSosXml', () => {
  it('reads an odds change with its markets, outcomes and clock', () => {
    const event = parseSosXml(`<?xml version="1.0"?>
      <odds_change product="1" event_id="sr:match:1" timestamp="1700000000000">
        <sport_event_status status="1" match_status="6" reporting="1"><clock match_time="1:30" round="2"/></sport_event_status>
        <odds>
          <market id="186" status="1"><outcome id="outcome:4" odds="1.5" active="1" probabilities="0.62"/><outcome id="outcome:5" odds="2.6" active="0"/></market>
          <market id="1510" status="1" specifiers="total=3.5|round=1"><outcome id="outcome:12" active="1"/></market>
        </odds>
      </odds_change>`) as OddsChangeEvent;

    assert.equal(event.eventId, 'sr:match:1');
    assert.equal(event.productId, 1);
    assert.deepEqual(event.sportEventStatus, { status: 1, matchStatus: 6, reporting: 1, clock: { matchTime: '1:30', round: 2 } });
    assert.equal(event.markets.length, 2);
    assert.deepEqual(event.markets[0].outcomes[0], { id: 'outcome:4', odds: 1.5, active: true, probabilities: 0.62 });
    assert.equal(event.markets[0].outcomes[1].active, false);
    assert.equal(event.markets[1].specifiers, 'total=3.5|round=1');
    assert.equal(event.markets[1].outcomes[0].odds, undefined);
  });

  it('reads an odds change with no markets and no clock', () => {
    const event = parseSosXml('<odds_change product="1" event_id="sr:match:2" timestamp="1"><odds/></odds_change>') as OddsChangeEvent;
    assert.deepEqual(event.markets, []);
    assert.equal(event.sportEventStatus.clock, undefined);
  });

  it('reads a settlement with won, lost, void and undecided outcomes and the factors', () => {
    const event = parseSosXml(`<bet_settlement product="1" event_id="sr:match:1" timestamp="2" certainty="2"><outcomes>
        <market id="186"><outcome id="a" result="1"/><outcome id="b" result="0"/></market>
        <market id="911" specifiers="total=1.5" void_reason="no contest"><outcome id="c" result="-1" void_factor="0.5" dead_heat_factor="1"/><outcome id="d" result="9"/></market>
      </outcomes></bet_settlement>`) as BetSettlementEvent;

    assert.equal(event.certainty, 2);
    assert.deepEqual(event.markets[0].outcomes.map(o => o.result), ['won', 'lost']);
    assert.deepEqual(event.markets[1].outcomes.map(o => o.result), ['void', 'undecided']);
    assert.equal(event.markets[1].outcomes[0].voidFactor, 0.5);
    assert.equal(event.markets[1].outcomes[0].deadHeatFactor, 1);
    assert.equal(event.markets[1].voidReason, 'no contest');
    assert.equal(event.markets[1].specifiers, 'total=1.5');
  });

  it('reads a bet stop, a bet cancel, a fixture change, a snapshot complete and an alive', () => {
    assert.deepEqual(parseSosXml('<bet_stop product="1" event_id="sr:match:1" timestamp="3"><groups>all</groups></bet_stop>'), {
      productId: 1, eventId: 'sr:match:1', timestamp: 3, groups: 'all',
    });
    const cancel = parseSosXml('<bet_cancel product="1" event_id="sr:match:1" timestamp="4" start_time="1" end_time="2"><market id="186" void_reason="x"/><market id="911"/></bet_cancel>') as BetCancelEvent;
    assert.deepEqual(cancel.markets, [{ id: 186, voidReason: 'x' }, { id: 911, voidReason: undefined }]);
    assert.equal(cancel.startTime, 1);
    assert.deepEqual(parseSosXml('<fixture_change product="1" event_id="sr:match:1" timestamp="5" start_time="6"/>'), {
      productId: 1, eventId: 'sr:match:1', timestamp: 5, startTime: 6,
    });
    assert.deepEqual(parseSosXml('<snapshot_complete product="1" request_id="req-1" timestamp="7"/>'), {
      productId: 1, requestId: 'req-1', timestamp: 7,
    });
    assert.deepEqual(parseSosXml('<alive product="1" timestamp="8" subscribed="1"/>'), { productId: 1, timestamp: 8, subscribed: true });
    assert.equal(parseSosXml('<fixtures/>'), null);
  });
});

import { XMLParser } from 'fast-xml-parser';
import {
  OddsChangeEvent,
  BetSettlementEvent,
  BetStopEvent,
  BetCancelEvent,
  FixtureChangeEvent,
  SnapshotCompleteEvent,
  AliveEvent,
  Market,
  Outcome,
  SettlementMarket,
  SettlementOutcome,
} from '../types';

const xmlParser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@_',
  allowBooleanAttributes: true,
  parseAttributeValue: true,
  isArray: (tagName) => ['market', 'outcome', 'competitor', 'result'].includes(tagName),
});

export function parseSosXml(
  xml: string,
): OddsChangeEvent | BetSettlementEvent | BetStopEvent | BetCancelEvent | FixtureChangeEvent | SnapshotCompleteEvent | AliveEvent | null {
  const parsed = xmlParser.parse(xml);

  if (parsed.odds_change) return parseOddsChange(parsed.odds_change);
  if (parsed.bet_settlement) return parseBetSettlement(parsed.bet_settlement);
  if (parsed.bet_stop) return parseBetStop(parsed.bet_stop);
  if (parsed.bet_cancel) return parseBetCancel(parsed.bet_cancel);
  if (parsed.fixture_change) return parseFixtureChange(parsed.fixture_change);
  if (parsed.snapshot_complete) return parseSnapshotComplete(parsed.snapshot_complete);
  if (parsed.alive) return parseAlive(parsed.alive);

  return null;
}

function parseOddsChange(oc: any): OddsChangeEvent {
  const markets: Market[] = [];

  const rawMarkets = oc.odds?.market || [];
  const marketArr = Array.isArray(rawMarkets) ? rawMarkets : [rawMarkets];

  for (const m of marketArr) {
    if (!m) continue;
    const rawOutcomes = m.outcome || [];
    const outcomeArr = Array.isArray(rawOutcomes) ? rawOutcomes : [rawOutcomes];

    const outcomes: Outcome[] = outcomeArr.map((o: any) => ({
      id: String(o['@_id']),
      odds: o['@_odds'] != null ? Number(o['@_odds']) : undefined,
      active: o['@_active'] === 1 || o['@_active'] === '1',
      probabilities: o['@_probabilities'] != null ? Number(o['@_probabilities']) : undefined,
    }));

    markets.push({
      id: Number(m['@_id']),
      specifiers: m['@_specifiers'] || undefined,
      status: Number(m['@_status']),
      outcomes,
    });
  }

  const ses = oc.sport_event_status || {};

  return {
    productId: Number(oc['@_product']),
    eventId: String(oc['@_event_id']),
    timestamp: Number(oc['@_timestamp']),
    sportEventStatus: {
      status: Number(ses['@_status'] ?? 0),
      matchStatus: Number(ses['@_match_status'] ?? 0),
      reporting: Number(ses['@_reporting'] ?? 0),
      clock: ses.clock ? {
        matchTime: ses.clock['@_match_time'],
        round: ses.clock['@_round'] != null ? Number(ses.clock['@_round']) : undefined,
      } : undefined,
    },
    markets,
  };
}

function parseBetSettlement(bs: any): BetSettlementEvent {
  const markets: SettlementMarket[] = [];

  const rawMarkets = bs.outcomes?.market || [];
  const marketArr = Array.isArray(rawMarkets) ? rawMarkets : [rawMarkets];

  for (const m of marketArr) {
    if (!m) continue;
    const rawOutcomes = m.outcome || [];
    const outcomeArr = Array.isArray(rawOutcomes) ? rawOutcomes : [rawOutcomes];

    const outcomes: SettlementOutcome[] = outcomeArr.map((o: any) => {
      const resultCode = String(o['@_result']);
      let result: SettlementOutcome['result'] = 'undecided';
      if (resultCode === '1') result = 'won';
      else if (resultCode === '0') result = 'lost';
      else if (resultCode === '-1') result = 'void';

      return {
        id: String(o['@_id']),
        result,
        voidFactor: o['@_void_factor'] != null && o['@_void_factor'] !== '' ? Number(o['@_void_factor']) : undefined,
        deadHeatFactor: o['@_dead_heat_factor'] != null && o['@_dead_heat_factor'] !== '' ? Number(o['@_dead_heat_factor']) : undefined,
      };
    });

    markets.push({
      id: Number(m['@_id']),
      specifiers: m['@_specifiers'] || undefined,
      voidReason: m['@_void_reason'] || undefined,
      outcomes,
    });
  }

  return {
    productId: Number(bs['@_product']),
    eventId: String(bs['@_event_id']),
    timestamp: Number(bs['@_timestamp']),
    certainty: Number(bs['@_certainty'] ?? 1),
    markets,
  };
}

function parseBetStop(stop: any): BetStopEvent {
  return {
    productId: Number(stop['@_product']),
    eventId: String(stop['@_event_id']),
    timestamp: Number(stop['@_timestamp']),
    groups: String(stop.groups || 'all'),
  };
}

function parseBetCancel(bc: any): BetCancelEvent {
  const rawMarkets = bc.market || [];
  const marketArr = Array.isArray(rawMarkets) ? rawMarkets : [rawMarkets];

  return {
    productId: Number(bc['@_product']),
    eventId: String(bc['@_event_id']),
    timestamp: Number(bc['@_timestamp']),
    startTime: bc['@_start_time'] != null ? Number(bc['@_start_time']) : undefined,
    endTime: bc['@_end_time'] != null ? Number(bc['@_end_time']) : undefined,
    markets: marketArr.filter(Boolean).map((m: any) => ({
      id: Number(m['@_id']),
      voidReason: m['@_void_reason'] != null ? m['@_void_reason'] : undefined,
    })),
  };
}

function parseFixtureChange(fc: any): FixtureChangeEvent {
  return {
    productId: Number(fc['@_product']),
    eventId: String(fc['@_event_id']),
    timestamp: Number(fc['@_timestamp']),
    startTime: fc['@_start_time'] != null ? Number(fc['@_start_time']) : undefined,
  };
}

function parseSnapshotComplete(sc: any): SnapshotCompleteEvent {
  return {
    productId: Number(sc['@_product']),
    requestId: String(sc['@_request_id']),
    timestamp: Number(sc['@_timestamp']),
  };
}

function parseAlive(alive: any): AliveEvent {
  return {
    productId: Number(alive['@_product']),
    timestamp: Number(alive['@_timestamp']),
    subscribed: alive['@_subscribed'] === 1 || alive['@_subscribed'] === '1',
  };
}

/**
 * Detect message type from raw XML without full parse.
 */
export function detectMessageType(xml: string): string | null {
  if (xml.includes('<odds_change')) return 'odds_change';
  if (xml.includes('<bet_settlement')) return 'bet_settlement';
  if (xml.includes('<bet_stop')) return 'bet_stop';
  if (xml.includes('<bet_cancel')) return 'bet_cancel';
  if (xml.includes('<fixture_change')) return 'fixture_change';
  if (xml.includes('<snapshot_complete')) return 'snapshot_complete';
  if (xml.includes('<alive')) return 'alive';
  return null;
}
